{
  "code": "/**
 * Form validation, saving, cancelling and reload restoration.
 */

function validateForm() {
  const nameInput = document.getElementById('mentor-name');
  const emailInput = document.getElementById('mentor-email');
  const errorEl = document.getElementById('form-error');
  let isValid = true;

  if (!nameInput.value.trim()) {
    nameInput.setCustomValidity('이름을 입력해주세요.');
    isValid = false;
  } else {
    nameInput.setCustomValidity('');
  }

  if (!emailInput.value.trim() || !/\S+@\S+\.\S+/.test(emailInput.value)) {
    emailInput.setCustomValidity('올바른 이메일을 입력해주세요.');
    isValid = false;
  } else {
    emailInput.setCustomValidity('');
  }

  if (errorEl) {
    errorEl.textContent = isValid ? '' : '입력값을 확인해주세요.';
    errorEl.classList.toggle('visible', !isValid);
  }

  return isValid;
}

function saveMentorRequest(formData) {
  try {
    localStorage.setItem('pending_mentor_request', JSON.stringify(formData));
    return true;
  } catch (e) {
    console.error('Save failed', e);
    const errorEl = document.getElementById('form-error');
    if (errorEl) {
      errorEl.textContent = '저장에 실패했습니다.';
      errorEl.classList.add('visible');
    }
    return false;
  }
}

function cancelMentorRequest() {
  localStorage.removeItem('pending_mentor_request');
  const form = document.getElementById('mentor-form');
  if (form) form.reset();
  const errorEl = document.getElementById('form-error');
  if (errorEl) {
    errorEl.textContent = '';
    errorEl.classList.remove('visible');
  }
}

function restoreFormState() {
  try {
    const saved = localStorage.getItem('pending_mentor_request');
    if (!saved) return;
    const data = JSON.parse(saved);
    const nameInput = document.getElementById('mentor-name');
    const emailInput = document.getElementById('mentor-email');
    if (nameInput) nameInput.value = data.name || '';
    if (emailInput) emailInput.value = data.email || '';
  } catch (e) {
    console.error('Restore failed', e);
  }
}

// Initialize application after handlers and functions exist
document.addEventListener('DOMContentLoaded', () => {
  restoreFormState();
  // Existing search/chip handlers would go here if not already present
});"
}
